_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")


def parse_aware(text: str):
    """An ISO 8601 time with `Z` or an offset (data.md, section 2), or None."""
    if not isinstance(text, str) or "T" not in text or not text.isascii():
        return None
    try:
        t = datetime.fromisoformat(text)
    except ValueError:
        return None
    if t.tzinfo is None or t.utcoffset() is None:
        return None
    return t


def parse_state(text):
    """A time of state.json: with `Z` or an offset, or the UTC form of release 1.2; None if neither."""
    if not isinstance(text, str):
        return None
    if _LEGACY.match(text):
        try:
            return datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return parse_aware(text)
